INSERT INTO `email_templates` VALUES (1,'inquiry_acknowledgement','Contact form — acknowledgement to visitor','We received your message ({{ reference }})','Thanks for reaching out, {{ name }}','We have received your inquiry and a member of our team will get back to you shortly, usually within one business day.\n\n**Your reference:** {{ reference }}\n\n**Subject:** {{ subject }}\n\nIf you need to add anything, simply reply to this email and quote your reference.','Visit our website',1,NULL,'2026-10-26 02:36:55','2026-10-26 02:36:55'),(2,'inquiry_notification','Contact form — new inquiry alert (internal)','New {{ type }}: {{ reference }} from {{ name }}','New inquiry received','**Reference:** {{ reference }}\n\n**From:** {{ name }} ({{ company }})\n\n**Service of interest:** {{ service }}\n\n**Budget:** {{ budget }} · **Timeline:** {{ timeline }}\n\n**Subject:** {{ subject }}\n\n{{ message_excerpt }}\n\nOpen the inquiry in the admin panel to view full details, attachments and assign it.','Open inquiry',1,NULL,'2026-10-26 02:36:55','2026-10-26 02:36:55'),(3,'feedback_notification','Client feedback — new submission alert (internal)','New client feedback ({{ rating }}/5) awaiting moderation','New feedback awaiting moderation','**Client:** {{ client_name }} ({{ company }})\n\n**Overall rating:** {{ rating }}/5\n\n**Permission to publish:** {{ publish_permission }}\n\n{{ feedback_excerpt }}\n\nReview it in the admin panel before anything is published.','Moderate feedback',1,NULL,'2026-10-26 02:36:55','2026-10-26 02:36:55'),(4,'feedback_verification','Client feedback — confirm email address','Please confirm your feedback for {{ company_name }}','Confirm your feedback','Hi {{ client_name }},\n\nThank you for sharing your experience with {{ company_name }}. Please confirm your email address so we can review your feedback.\n\nIf you did not submit feedback, you can ignore this email.','Confirm my feedback',1,NULL,'2026-10-26 02:36:55','2026-10-26 02:36:55'),(5,'testimonial_approved','Client feedback — published notice','Your feedback is now live','Thank you, {{ client_name }}','Your feedback has been approved and published on our website. We truly appreciate you taking the time to share your experience with {{ company_name }}.','View reviews',1,NULL,'2026-10-26 02:36:55','2026-10-26 02:36:55'),(6,'testimonial_reply','Client feedback — private reply','A reply to your feedback','Hi {{ client_name }}','{{ reply }}\n\n— The {{ company_name }} team',NULL,1,NULL,'2026-10-26 02:36:55','2026-10-26 02:36:55'),(7,'job_application_acknowledgement','Careers — application acknowledgement','We received your application ({{ reference }})','Thanks for applying, {{ name }}','We have received your application for **{{ position }}**. Our team reviews every application carefully and will contact you if your profile matches the role.\n\n**Your reference:** {{ reference }}','See other openings',1,NULL,'2026-10-26 02:36:55','2026-10-26 02:36:55'),(8,'job_application_notification','Careers — new application alert (internal)','New application for {{ position }}: {{ name }}','New job application','**Reference:** {{ reference }}\n\n**Candidate:** {{ name }}\n\n**Position:** {{ position }}\n\nOpen the application in the admin panel to review the résumé.','Open application',1,NULL,'2026-10-26 02:36:55','2026-10-26 02:36:55'),(9,'newsletter_confirmation','Newsletter — confirm subscription','Confirm your subscription to {{ company_name }} insights','One more step','Please confirm that you would like to receive occasional insights and updates from {{ company_name }}. You can unsubscribe at any time.\n\nIf you did not request this, you can ignore this email.','Confirm subscription',1,NULL,'2026-10-26 02:36:55','2026-10-26 02:36:55'),(10,'user_invitation','Admin — account invitation','You have been invited to the {{ company_name }} admin panel','Welcome, {{ name }}','An administrator has created an account for you with the role **{{ roles }}**.\n\nUse the button below to choose your password. The link expires in 60 minutes; you can request a new one from the sign-in page.','Set my password',1,NULL,'2026-10-26 02:36:55','2026-10-26 02:36:55'),(11,'security_alert','Admin — security notification','Security notice for your {{ company_name }} account','Security notice','Hi {{ name }},\n\n{{ event }}\n\n**When:** {{ time }}\n\nIf this was not you, reset your password immediately and contact your administrator.','Open admin panel',1,NULL,'2026-10-26 02:36:55','2026-10-26 02:36:55'),(12,'test_email','System — test email','Test email from {{ company_name }}','Email delivery works','This is a test message sent by {{ name }} from the admin panel at {{ time }}.\n\nIf you can read this, outgoing email is configured correctly.',NULL,1,NULL,'2026-10-26 02:36:55','2026-10-26 02:36:55');
