INSERT INTO `industries` VALUES (1,'Healthcare','healthcare','heart','Secure, compliant digital tools for providers, clinics and health-tech innovators.','<p>Healthcare organisations need technology that is secure, reliable and easy to use for patients and clinicians alike. Fragmented records, manual scheduling and paper-based processes consume time that should be spent on care, while patients increasingly expect digital access to appointments, results and advice.</p>\n<p>Every healthcare project begins by mapping how patients, clinicians and administrators actually work today, including the workarounds that have grown up around existing systems. That understanding helps us prioritise improvements that remove genuine friction, introduce change gradually and avoid adding yet another login or screen to already busy working days.</p>\n<h2>How we help</h2>\n<ul>\n<li><strong>Patient portals and mobile apps</strong> for bookings, reminders, secure messaging and documents.</li>\n<li><strong>Telehealth solutions</strong> that integrate with existing scheduling and records systems.</li>\n<li><strong>Workflow automation</strong> for referrals, intake forms and administrative tasks.</li>\n<li><strong>AI-assisted document processing</strong> with clinicians reviewing outputs.</li>\n<li><strong>Analytics dashboards</strong> that help managers plan capacity and track service levels.</li>\n</ul>\n<h2>Built for trust</h2>\n<p>We design with data protection at the core: role-based access, encryption, audit logging and careful handling of sensitive information in line with applicable regulations. Accessibility matters too, because healthcare services must work for people of all ages and abilities. Our <a href=\"/services/mobile-application-development\" rel=\"noopener noreferrer\">mobile app</a>, <a href=\"/services/custom-software-development\" rel=\"noopener noreferrer\">custom software</a> and <a href=\"/services/cybersecurity-consulting\" rel=\"noopener noreferrer\">cybersecurity</a> teams work together so innovation never comes at the expense of safety.</p>','[{\"icon\": \"exclamation-triangle\", \"title\": \"Protecting sensitive patient data\", \"description\": null}, {\"icon\": \"exclamation-triangle\", \"title\": \"Fragmented records and manual scheduling\", \"description\": null}, {\"icon\": \"exclamation-triangle\", \"title\": \"Delivering care remotely\", \"description\": null}]','[{\"icon\": \"check-badge\", \"title\": \"Patient portals and telehealth apps\", \"description\": null}, {\"icon\": \"check-badge\", \"title\": \"Integrated scheduling and records\", \"description\": null}, {\"icon\": \"check-badge\", \"title\": \"AI-assisted document processing\", \"description\": null}]',NULL,'published','2026-10-26 02:36:55',1,0,0,NULL,NULL,'2026-10-26 02:36:55','2026-10-26 04:04:33',NULL,NULL),(2,'Education','education','academic-cap','Learning platforms, student systems and AI tutors for schools, universities and ed-tech.','<p>Education providers balance engaging learners, supporting staff and managing complex administration — often with limited budgets and legacy systems. Digital tools can personalise learning, reduce paperwork and give leaders better insight into progress and outcomes.</p>\n<p>We work with schools, colleges, universities and private training providers, adapting our approach to each setting. A small academy may need a simple, well-designed portal, while a larger institution may need integration with existing student records, single sign-on and reporting. In every case we involve teachers and administrators early, so the tools fit real timetables and workloads.</p>\n<h2>How we help</h2>\n<ul>\n<li><strong>Learning platforms</strong> with courses, assessments, progress tracking and content management.</li>\n<li><strong>Student information and enrolment systems</strong> that replace spreadsheets and paper forms.</li>\n<li><strong>Generative AI study assistants</strong> grounded in approved course material, with safeguards.</li>\n<li><strong>Mobile apps</strong> for timetables, notifications and communication with students and parents.</li>\n<li><strong>Analytics</strong> that help staff identify learners who need extra support.</li>\n</ul>\n<h2>Accessible and responsible</h2>\n<p>Educational technology must be inclusive, so we design to accessibility guidelines and test with diverse users. We take particular care with learners&#039; personal data and with AI features, keeping educators in control of content and decisions. Explore our <a href=\"/services/web-application-development\" rel=\"noopener noreferrer\">web application</a>, <a href=\"/services/generative-ai-ai-agent-development\" rel=\"noopener noreferrer\">generative AI</a> and <a href=\"/services/uiux-design\" rel=\"noopener noreferrer\">UI/UX design</a> services to see how we approach education projects.</p>','[{\"icon\": \"exclamation-triangle\", \"title\": \"Engaging learners online\", \"description\": null}, {\"icon\": \"exclamation-triangle\", \"title\": \"Administrative overhead for staff\", \"description\": null}, {\"icon\": \"exclamation-triangle\", \"title\": \"Personalising learning at scale\", \"description\": null}]','[{\"icon\": \"check-badge\", \"title\": \"Learning management platforms\", \"description\": null}, {\"icon\": \"check-badge\", \"title\": \"Student information systems\", \"description\": null}, {\"icon\": \"check-badge\", \"title\": \"Generative AI study assistants\", \"description\": null}]',NULL,'published','2026-10-26 02:36:55',1,1,0,NULL,NULL,'2026-10-26 02:36:55','2026-10-26 04:04:33',NULL,NULL),(3,'Finance & Fintech','finance-fintech','banknotes','Secure, scalable platforms for payments, lending, wealth and financial operations.','<p>Financial services demand the highest standards of security, accuracy and reliability. At the same time, customers expect fast digital onboarding, real-time information and seamless experiences, while back offices still rely heavily on manual review and legacy core systems.</p>\n<p>Whether you are a fintech launching a new product or an established firm modernising its customer journeys, we start by understanding your regulatory context, risk appetite and existing technology. That lets us design solutions that fit your compliance processes from day one, rather than retrofitting controls later, and phase delivery so that risk stays manageable throughout.</p>\n<h2>How we help</h2>\n<ul>\n<li><strong>Customer portals and mobile apps</strong> for accounts, applications and secure document exchange.</li>\n<li><strong>APIs and integrations</strong> that connect modern products with existing core systems and partners.</li>\n<li><strong>Process automation</strong> for onboarding checks, document handling and reconciliations.</li>\n<li><strong>AI and analytics</strong> to surface anomalies and risk signals for expert review.</li>\n<li><strong>Reporting dashboards</strong> that give teams timely, consistent information.</li>\n</ul>\n<h2>Security and governance first</h2>\n<p>We build with strong authentication, least-privilege access, encryption, comprehensive audit trails and rigorous testing. AI-supported decisions keep humans accountable, with explainable outputs and clear review steps. Our <a href=\"/services/api-development-system-integration\" rel=\"noopener noreferrer\">API and integration</a>, <a href=\"/services/business-process-automation\" rel=\"noopener noreferrer\">automation</a> and <a href=\"/services/cybersecurity-consulting\" rel=\"noopener noreferrer\">cybersecurity</a> specialists work together to deliver solutions that are both innovative and dependable.</p>','[{\"icon\": \"exclamation-triangle\", \"title\": \"Strict security and regulatory requirements\", \"description\": null}, {\"icon\": \"exclamation-triangle\", \"title\": \"Fraud and risk detection\", \"description\": null}, {\"icon\": \"exclamation-triangle\", \"title\": \"Legacy core systems\", \"description\": null}]','[{\"icon\": \"check-badge\", \"title\": \"Secure customer portals and APIs\", \"description\": null}, {\"icon\": \"check-badge\", \"title\": \"Anomaly and fraud detection models\", \"description\": null}, {\"icon\": \"check-badge\", \"title\": \"Process automation for back-office\", \"description\": null}]',NULL,'published','2026-10-26 02:36:55',1,2,0,NULL,NULL,'2026-10-26 02:36:55','2026-10-26 04:04:33',NULL,NULL),(4,'Retail & E-commerce','retail-e-commerce','building-storefront','Omnichannel commerce, inventory and personalisation that grow revenue.','<p>Retail moves quickly. Customers compare options in seconds, expect accurate stock information and want a consistent experience whether they shop online, on mobile or in store. Behind the scenes, retailers juggle inventory across channels, promotions, fulfilment and returns.</p>\n<p>Whether you are launching your first online shop or scaling an established multichannel operation, we focus on the details that influence buying decisions: fast pages, clear product information, smooth checkout and reliable delivery updates. We also look at the operational side, because accurate stock, efficient fulfilment and easy returns matter just as much to customer loyalty.</p>\n<h2>How we help</h2>\n<ul>\n<li><strong>High-performance storefronts</strong> — platform-based, custom or headless — optimised for mobile.</li>\n<li><strong>Unified order and inventory management</strong> integrated with warehouses, ERP and marketplaces.</li>\n<li><strong>Personalisation and recommendations</strong> that help customers find the right products.</li>\n<li><strong>Customer apps and loyalty features</strong> that encourage repeat purchases.</li>\n<li><strong>Analytics</strong> covering conversion, basket value, stock and campaign performance.</li>\n</ul>\n<h2>Ready for peak demand</h2>\n<p>We plan for seasonal peaks with scalable cloud hosting and load testing, and design checkout journeys that are fast, clear and trustworthy. Search-friendly product pages and structured data help shoppers find you. Learn more about our <a href=\"/services/e-commerce-development\" rel=\"noopener noreferrer\">e-commerce development</a>, <a href=\"/services/data-analytics-business-intelligence\" rel=\"noopener noreferrer\">analytics</a> and <a href=\"/services/ai-machine-learning-solutions\" rel=\"noopener noreferrer\">AI</a> services.</p>','[{\"icon\": \"exclamation-triangle\", \"title\": \"Abandoned carts and slow storefronts\", \"description\": null}, {\"icon\": \"exclamation-triangle\", \"title\": \"Inventory across channels\", \"description\": null}, {\"icon\": \"exclamation-triangle\", \"title\": \"Personalising customer journeys\", \"description\": null}]','[{\"icon\": \"check-badge\", \"title\": \"Fast headless storefronts\", \"description\": null}, {\"icon\": \"check-badge\", \"title\": \"Unified order and inventory management\", \"description\": null}, {\"icon\": \"check-badge\", \"title\": \"Recommendation engines\", \"description\": null}]',NULL,'published','2026-10-26 02:36:55',1,3,0,NULL,NULL,'2026-10-26 02:36:55','2026-10-26 04:04:33',NULL,NULL),(5,'Manufacturing','manufacturing','cog-6-tooth','Connected operations, ERP and predictive analytics for modern manufacturers.','<p>Manufacturers depend on efficient, predictable operations. Unplanned downtime, disconnected shop-floor and office systems, and manual quality checks all erode margins. Connecting data across machines, production planning and business systems creates the visibility needed to improve.</p>\n<p>We take time to understand your production environment, from the machines and systems already in place to the people who operate them every shift. That grounding helps us propose realistic improvements that respect safety requirements, existing investments and the practical constraints of the shop floor, rather than theoretical solutions that are difficult to adopt.</p>\n<h2>How we help</h2>\n<ul>\n<li><strong>ERP and production system integrations</strong> that remove manual data transfer.</li>\n<li><strong>Real-time production dashboards</strong> for output, utilisation and quality.</li>\n<li><strong>Predictive maintenance analytics</strong> using equipment and sensor data where available.</li>\n<li><strong>Computer-vision quality inspection</strong> to support consistent, faster checks.</li>\n<li><strong>Custom applications</strong> for planning, traceability and supplier collaboration.</li>\n</ul>\n<h2>Practical, phased modernisation</h2>\n<p>We start with the processes that cause the most friction and build on existing systems rather than replacing everything at once. Solutions are designed to be robust in industrial environments and easy for operators to use. See our <a href=\"/services/crm-erp-solutions\" rel=\"noopener noreferrer\">CRM and ERP</a>, <a href=\"/services/data-analytics-business-intelligence\" rel=\"noopener noreferrer\">data analytics</a> and <a href=\"/services/ai-machine-learning-solutions\" rel=\"noopener noreferrer\">AI and machine learning</a> services.</p>','[{\"icon\": \"exclamation-triangle\", \"title\": \"Unplanned equipment downtime\", \"description\": null}, {\"icon\": \"exclamation-triangle\", \"title\": \"Disconnected shop-floor and ERP data\", \"description\": null}, {\"icon\": \"exclamation-triangle\", \"title\": \"Manual quality control\", \"description\": null}]','[{\"icon\": \"check-badge\", \"title\": \"ERP and MES integrations\", \"description\": null}, {\"icon\": \"check-badge\", \"title\": \"Predictive maintenance analytics\", \"description\": null}, {\"icon\": \"check-badge\", \"title\": \"Computer-vision quality checks\", \"description\": null}]',NULL,'published','2026-10-26 02:36:55',1,4,0,NULL,NULL,'2026-10-26 02:36:55','2026-10-26 04:04:33',NULL,NULL),(6,'Logistics','logistics','truck','Tracking, routing and warehouse systems that keep goods moving efficiently.','<p>Logistics businesses operate on tight margins and tighter schedules. Customers want real-time visibility of their shipments, drivers need simple tools on the road, and warehouses must process orders accurately at speed. Paper-based processes and disconnected systems make all of this harder.</p>\n<p>We understand that logistics software must cope with the unexpected: patchy mobile signal, late changes, exceptions and peak-season volumes. That is why we design for resilience, test with real operational scenarios and keep interfaces simple for people who are often working against the clock. Practical tools that teams trust get used consistently, which is where the value lies.</p><p>We also help logistics firms make better use of the data they already collect, turning scan events, delivery times and exceptions into clear reports that reveal recurring bottlenecks and support continuous improvement across depots and routes.</p>\n<h2>How we help</h2>\n<ul>\n<li><strong>Customer tracking portals</strong> with live status updates and proof of delivery.</li>\n<li><strong>Mobile apps for drivers and warehouse teams</strong> that work reliably offline.</li>\n<li><strong>Route and capacity planning tools</strong> that support better scheduling decisions.</li>\n<li><strong>Automation</strong> for documents, booking confirmations and exception alerts.</li>\n<li><strong>Integrations</strong> with carriers, warehouse management and accounting systems.</li>\n</ul>\n<h2>Visibility end to end</h2>\n<p>By connecting data from bookings to delivery, logistics teams can spot delays earlier, communicate proactively with customers and reduce manual follow-up. Explore our <a href=\"/services/mobile-application-development\" rel=\"noopener noreferrer\">mobile app development</a>, <a href=\"/services/business-process-automation\" rel=\"noopener noreferrer\">process automation</a> and <a href=\"/services/api-development-system-integration\" rel=\"noopener noreferrer\">integration</a> services.</p>','[{\"icon\": \"exclamation-triangle\", \"title\": \"Limited shipment visibility\", \"description\": null}, {\"icon\": \"exclamation-triangle\", \"title\": \"Inefficient routing\", \"description\": null}, {\"icon\": \"exclamation-triangle\", \"title\": \"Paper-based warehouse processes\", \"description\": null}]','[{\"icon\": \"check-badge\", \"title\": \"Real-time tracking portals\", \"description\": null}, {\"icon\": \"check-badge\", \"title\": \"Route optimisation\", \"description\": null}, {\"icon\": \"check-badge\", \"title\": \"Mobile warehouse apps\", \"description\": null}]',NULL,'published','2026-10-26 02:36:55',1,5,0,NULL,NULL,'2026-10-26 02:36:55','2026-10-26 04:04:33',NULL,NULL),(7,'Real Estate','real-estate','home-modern','Property platforms, CRMs and automation for agencies, developers and property managers.','<p>Real estate businesses manage leads from many channels, large volumes of property data and ongoing relationships with buyers, tenants and owners. When these live in separate tools, opportunities slip through the cracks and teams spend too long on administration.</p>\n<p>Agencies, developers and property managers each have different priorities, so we begin by understanding how leads arrive, how properties are marketed and how relationships are maintained after a sale or let. From there we design tools that fit those processes and integrate with the portals, accounting and communication systems your team already relies on.</p><p>Search-friendly listing pages, fast mobile experiences and timely notifications help you stand out in a competitive market, while automation frees agents and property managers to spend more time with clients.</p>\n<h2>How we help</h2>\n<ul>\n<li><strong>Listing portals</strong> with rich property pages, search and enquiry handling.</li>\n<li><strong>Property CRM</strong> to track leads, viewings, offers and follow-ups.</li>\n<li><strong>Tenant and owner portals</strong> for documents, payments and maintenance requests.</li>\n<li><strong>Automated maintenance workflows</strong> that assign, track and report jobs.</li>\n<li><strong>Analytics</strong> on enquiries, occupancy and portfolio performance.</li>\n</ul>\n<h2>Better experiences for everyone</h2>\n<p>Well-designed digital tools respond to enquiries faster, keep tenants informed and give managers a clear view of their portfolio. Learn more about our <a href=\"/services/web-application-development\" rel=\"noopener noreferrer\">web application</a>, <a href=\"/services/crm-erp-solutions\" rel=\"noopener noreferrer\">CRM</a> and <a href=\"/services/business-process-automation\" rel=\"noopener noreferrer\">automation</a> services.</p>','[{\"icon\": \"exclamation-triangle\", \"title\": \"Managing leads across channels\", \"description\": null}, {\"icon\": \"exclamation-triangle\", \"title\": \"Manual tenancy and maintenance workflows\", \"description\": null}, {\"icon\": \"exclamation-triangle\", \"title\": \"Showcasing listings online\", \"description\": null}]','[{\"icon\": \"check-badge\", \"title\": \"Listing portals and virtual tours\", \"description\": null}, {\"icon\": \"check-badge\", \"title\": \"Property CRM and tenant portals\", \"description\": null}, {\"icon\": \"check-badge\", \"title\": \"Automated maintenance workflows\", \"description\": null}]',NULL,'published','2026-10-26 02:36:55',0,6,0,NULL,NULL,'2026-10-26 02:36:55','2026-10-26 04:04:33',NULL,NULL),(8,'Travel & Hospitality','travel-hospitality','paper-airplane','Booking engines, guest apps and integrations for travel and hospitality brands.','<p>Travel and hospitality brands compete on experience. Guests expect easy booking, timely information and personal service, while operators manage complex inventory, multiple distribution channels and sharp seasonal swings in demand.</p>\n<p>We work with travel companies, tour operators, hotels and hospitality groups that want to modernise how they sell and serve. Whether you are replacing a dated booking flow or building a new digital product, we start by understanding your guests, your distribution partners and your operational systems so the solution fits the whole picture.</p><p>We also help teams make better use of booking and feedback data, providing reporting that supports pricing, staffing and marketing decisions across seasons.</p>\n<h2>How we help</h2>\n<ul>\n<li><strong>Booking engines</strong> with availability, pricing rules and secure payments.</li>\n<li><strong>Channel and partner integrations</strong> that keep inventory and rates in sync.</li>\n<li><strong>Guest experience apps</strong> for itineraries, check-in, requests and offers.</li>\n<li><strong>AI assistants</strong> that answer common questions grounded in your information.</li>\n<li><strong>Scalable cloud infrastructure</strong> that handles peak periods smoothly.</li>\n</ul>\n<h2>Designed around the guest</h2>\n<p>We design journeys that feel effortless on mobile, integrate the systems behind them and make sure platforms stay responsive when demand surges. See our <a href=\"/services/api-development-system-integration\" rel=\"noopener noreferrer\">integration</a>, <a href=\"/services/mobile-application-development\" rel=\"noopener noreferrer\">mobile app</a> and <a href=\"/services/cloud-computing-cloud-migration\" rel=\"noopener noreferrer\">cloud</a> services.</p>','[{\"icon\": \"exclamation-triangle\", \"title\": \"Complex booking and channel integrations\", \"description\": null}, {\"icon\": \"exclamation-triangle\", \"title\": \"Delivering memorable guest experiences\", \"description\": null}, {\"icon\": \"exclamation-triangle\", \"title\": \"Seasonal demand spikes\", \"description\": null}]','[{\"icon\": \"check-badge\", \"title\": \"Booking engines and channel managers\", \"description\": null}, {\"icon\": \"check-badge\", \"title\": \"Guest experience apps\", \"description\": null}, {\"icon\": \"check-badge\", \"title\": \"Elastic cloud infrastructure\", \"description\": null}]',NULL,'published','2026-10-26 02:36:55',0,7,0,NULL,NULL,'2026-10-26 02:36:55','2026-10-26 04:04:33',NULL,NULL),(9,'Professional Services','professional-services','scale','Client portals, knowledge tools and automation for consultancies, legal and accounting firms.','<p>Consultancies, legal practices and accounting firms sell expertise, yet much of their time is consumed by administration: gathering documents, searching for past work, tracking time and preparing reports. Clients increasingly expect secure, convenient digital collaboration.</p>\n<p>We begin by understanding how work flows through your firm, from first enquiry to final invoice, and where expertise is lost to repetitive tasks. That insight lets us prioritise improvements that free professionals to focus on advice and relationships, while giving clients a more transparent, responsive experience that reflects the quality of your work.</p><p>Solutions are introduced gradually, with training and support, so partners and staff adopt new tools with confidence.</p>\n<h2>How we help</h2>\n<ul>\n<li><strong>Secure client portals</strong> for document exchange, approvals and status updates.</li>\n<li><strong>AI knowledge assistants</strong> that find relevant precedents and internal know-how with citations.</li>\n<li><strong>Workflow automation</strong> for intake, engagement letters, time capture and billing.</li>\n<li><strong>Document intelligence</strong> for summarising and extracting key information, reviewed by experts.</li>\n<li><strong>Dashboards</strong> for utilisation, pipeline and profitability.</li>\n</ul>\n<h2>Confidentiality by design</h2>\n<p>Client confidentiality is paramount, so we build with strict access controls, encryption and audit logging, and choose AI deployment options that respect your data obligations. Explore our <a href=\"/services/generative-ai-ai-agent-development\" rel=\"noopener noreferrer\">generative AI</a>, <a href=\"/services/custom-software-development\" rel=\"noopener noreferrer\">custom software</a> and <a href=\"/services/cybersecurity-consulting\" rel=\"noopener noreferrer\">cybersecurity</a> services.</p>','[{\"icon\": \"exclamation-triangle\", \"title\": \"Time lost on administrative tasks\", \"description\": null}, {\"icon\": \"exclamation-triangle\", \"title\": \"Secure document sharing with clients\", \"description\": null}, {\"icon\": \"exclamation-triangle\", \"title\": \"Finding knowledge across the firm\", \"description\": null}]','[{\"icon\": \"check-badge\", \"title\": \"Secure client portals\", \"description\": null}, {\"icon\": \"check-badge\", \"title\": \"AI knowledge assistants\", \"description\": null}, {\"icon\": \"check-badge\", \"title\": \"Automated time and billing workflows\", \"description\": null}]',NULL,'published','2026-10-26 02:36:55',0,8,0,NULL,NULL,'2026-10-26 02:36:55','2026-10-26 04:04:33',NULL,NULL),(10,'Startups & Enterprises','startups-enterprises','rocket-launch','MVPs for founders and modernisation programmes for established organisations.','<p>Startups and enterprises face very different challenges, but both need technology partners who understand their pace and constraints. Founders need to validate ideas quickly without accumulating crippling technical debt. Established organisations need to modernise legacy systems and processes without disrupting the business.</p>\n<p>Whatever your stage, we bring the same disciplines to every engagement: clear priorities, transparent communication, secure engineering and a focus on measurable outcomes. We adapt team size, governance and documentation to your context, so a seed-stage founder and a large organisation both get an approach that fits rather than a one-size-fits-all process.</p>\n<h2>For startups</h2>\n<ul>\n<li><strong>Discovery and prototyping</strong> to test ideas with real users.</li>\n<li><strong>Lean MVP delivery</strong> focused on the core problem.</li>\n<li><strong>Scalable SaaS architecture</strong> that grows with traction.</li>\n<li><strong>Flexible engagement</strong> as funding and priorities evolve.</li>\n</ul>\n<h2>For enterprises</h2>\n<ul>\n<li><strong>Digital transformation roadmaps</strong> with clear priorities and outcomes.</li>\n<li><strong>Phased modernisation</strong> of legacy applications and infrastructure.</li>\n<li><strong>Integration</strong> across complex system landscapes.</li>\n<li><strong>AI adoption</strong> with governance, security and change management.</li>\n</ul>\n<p>Many of our clients sit between these two worlds — a scale-up formalising its processes, or an enterprise team running an innovation project with startup speed. We are comfortable moving between both modes as your needs change.</p>\n<p>Learn more about <a href=\"/services/saas-product-development\" rel=\"noopener noreferrer\">SaaS product development</a>, <a href=\"/services/digital-transformation-consulting\" rel=\"noopener noreferrer\">digital transformation consulting</a> and our flexible <a href=\"/engagement-models\" rel=\"noopener noreferrer\">engagement models</a>.</p>','[{\"icon\": \"exclamation-triangle\", \"title\": \"Validating ideas quickly\", \"description\": null}, {\"icon\": \"exclamation-triangle\", \"title\": \"Scaling products and teams\", \"description\": null}, {\"icon\": \"exclamation-triangle\", \"title\": \"Modernising legacy estates\", \"description\": null}]','[{\"icon\": \"check-badge\", \"title\": \"Lean MVP delivery\", \"description\": null}, {\"icon\": \"check-badge\", \"title\": \"Scalable SaaS architecture\", \"description\": null}, {\"icon\": \"check-badge\", \"title\": \"Digital transformation roadmaps\", \"description\": null}]',NULL,'published','2026-10-26 02:36:55',0,9,0,NULL,NULL,'2026-10-26 02:36:55','2026-10-26 04:04:33',NULL,NULL);
