INSERT INTO `page_sections` VALUES (1,1,'hero',NULL,'AI-first software engineering','Build smarter software with [AI at the core]','Softec Ai Solution designs, builds and scales custom software, AI and cloud solutions that help ambitious organisations work smarter and grow faster.',NULL,'{\"highlights\": [\"Custom software\", \"Generative AI\", \"Cloud & DevOps\", \"Product design\"], \"primary_cta\": {\"url\": \"/start-a-project\", \"label\": \"Start a project\"}, \"secondary_cta\": {\"url\": \"/services\", \"label\": \"Explore services\"}}',NULL,'default',NULL,0,1,'2026-10-26 02:36:55','2026-10-26 02:36:55'),(2,1,'logos',NULL,NULL,'Organisations we work with',NULL,NULL,'{\"limit\": 12, \"style\": \"marquee\", \"source\": \"clients\"}',NULL,'default',NULL,1,1,'2026-10-26 02:36:55','2026-10-26 02:36:55'),(3,1,'services',NULL,'What we do','IT services that [move your business forward]','From strategy and design to engineering, AI and cloud operations — one partner for the full lifecycle of your digital products.',NULL,'{\"mode\": \"featured\", \"limit\": 6}',NULL,'default',NULL,2,1,'2026-10-26 02:36:55','2026-10-26 02:36:55'),(4,1,'stats',NULL,'By the numbers','Softec Ai Solution [at a glance]',NULL,NULL,NULL,NULL,'contrast',NULL,4,1,'2026-10-26 02:36:55','2026-10-26 04:04:33'),(5,1,'why_choose',NULL,'Why Softec Ai Solution','A partner focused on [outcomes], not just output',NULL,NULL,'{\"items\": [{\"icon\": \"sparkles\", \"title\": \"AI-first engineering\", \"description\": \"We look for practical ways AI and automation can add value in every solution we build.\"}, {\"icon\": \"presentation-chart-line\", \"title\": \"Transparent delivery\", \"description\": \"Clear estimates, regular demos and honest progress reporting throughout your project.\"}, {\"icon\": \"shield-check\", \"title\": \"Security by design\", \"description\": \"Secure architecture, code review and least-privilege access are part of how we work.\"}, {\"icon\": \"squares-2x2\", \"title\": \"Full-stack capability\", \"description\": \"Design, development, data, cloud and support from one coordinated team.\"}, {\"icon\": \"arrow-trending-up\", \"title\": \"Built to evolve\", \"description\": \"Maintainable, documented code and architecture that grows with your business.\"}, {\"icon\": \"hand-raised\", \"title\": \"Long-term partnership\", \"description\": \"We stay with you after launch with support, optimisation and new features.\"}]}',NULL,'default',NULL,5,1,'2026-10-26 02:36:55','2026-10-26 04:04:33'),(6,1,'products',NULL,'Products','Software solutions [ready to adapt] to your business',NULL,NULL,'{\"limit\": 3}',NULL,'muted',NULL,6,1,'2026-10-26 02:36:55','2026-10-26 04:04:33'),(7,1,'industries',NULL,'Industries','Domain-aware solutions for [every sector]',NULL,NULL,'{\"limit\": 6, \"layout\": \"tabs\"}',NULL,'default',NULL,7,1,'2026-10-26 02:36:55','2026-10-26 04:04:33'),(8,1,'tech_stack',NULL,'Technology','Modern, [proven] technology stack','We choose tools for reliability, security and long-term maintainability.',NULL,NULL,NULL,'default',NULL,8,1,'2026-10-26 02:36:55','2026-10-26 04:04:33'),(9,1,'case_studies',NULL,'Case studies','Work we are [proud of]',NULL,NULL,'{\"limit\": 3}',NULL,'muted',NULL,9,1,'2026-10-26 02:36:55','2026-10-26 04:04:33'),(10,1,'process',NULL,'How we work','A clear path from [idea to impact]',NULL,NULL,'{\"items\": [{\"icon\": \"magnifying-glass-circle\", \"title\": \"Discover\", \"description\": \"Workshops to understand your goals, users, constraints and how success will be measured.\"}, {\"icon\": \"map\", \"title\": \"Plan & design\", \"description\": \"Architecture, scope, roadmap and UX prototypes agreed before development starts.\"}, {\"icon\": \"code-bracket\", \"title\": \"Build iteratively\", \"description\": \"Short sprints with regular demos, code review and automated testing.\"}, {\"icon\": \"rocket-launch\", \"title\": \"Launch\", \"description\": \"Hardened deployment, data migration, monitoring and team handover.\"}, {\"icon\": \"arrow-trending-up\", \"title\": \"Support & evolve\", \"description\": \"Maintenance, optimisation and new features as your needs grow.\"}]}',NULL,'default',NULL,10,1,'2026-10-26 02:36:55','2026-10-26 04:04:33'),(11,1,'testimonials',NULL,'Client feedback','What our [clients say]',NULL,NULL,'{\"limit\": 6}',NULL,'default',NULL,11,1,'2026-10-26 02:36:55','2026-10-26 04:04:33'),(12,1,'blog',NULL,'Insights','Ideas from our [engineers and consultants]',NULL,NULL,'{\"limit\": 3}',NULL,'default',NULL,12,1,'2026-10-26 02:36:55','2026-10-26 04:04:33'),(13,1,'faq',NULL,'FAQ','Frequently asked questions',NULL,NULL,'{\"limit\": 6}',NULL,'default',NULL,14,1,'2026-10-26 02:36:55','2026-10-26 04:04:33'),(14,1,'cta',NULL,NULL,'Have a [project] in mind?','Tell us about your goals and we will propose the right team, approach and plan.',NULL,'{\"primary_cta\": {\"url\": \"/start-a-project\", \"label\": \"Start a project\"}, \"secondary_cta\": {\"url\": \"/contact\", \"label\": \"Contact us\"}}',NULL,'gradient',NULL,15,1,'2026-10-26 02:36:55','2026-10-26 04:04:33'),(15,2,'rich_text',NULL,'Who we are','Engineering, AI and design [under one roof]',NULL,'<p>Softec Ai Solution is an IT services and product company. We help startups, growing businesses and enterprises turn ideas into reliable software — combining product thinking, modern engineering, artificial intelligence and cloud expertise.</p><p>Our teams work closely with clients from discovery to launch and beyond, focusing on outcomes that matter: better customer experiences, more efficient operations and new sources of growth.</p>',NULL,NULL,'default',NULL,0,1,'2026-10-26 02:36:55','2026-10-26 02:36:55'),(16,2,'values',NULL,'Purpose','Mission, vision [and values]',NULL,NULL,'{\"items\": [{\"icon\": \"check-badge\", \"title\": \"Integrity\", \"description\": \"Honest advice, transparent pricing and doing what we say.\"}, {\"icon\": \"code-bracket\", \"title\": \"Craftsmanship\", \"description\": \"Thoughtful design and clean, tested, maintainable code.\"}, {\"icon\": \"light-bulb\", \"title\": \"Curiosity\", \"description\": \"Continuous learning and pragmatic innovation.\"}, {\"icon\": \"hand-raised\", \"title\": \"Partnership\", \"description\": \"Your success is the measure of ours.\"}], \"vision\": \"A world where every organisation can use technology and AI confidently to create value for people.\", \"mission\": \"To help organisations work smarter by delivering secure, intelligent and well-crafted software.\"}',NULL,'muted',NULL,1,1,'2026-10-26 02:36:55','2026-10-26 02:36:55'),(17,2,'stats',NULL,'At a glance','Softec Ai Solution in numbers',NULL,NULL,NULL,NULL,'default',NULL,2,1,'2026-10-26 02:36:55','2026-10-26 02:36:55'),(18,2,'milestones',NULL,'Our story','Milestones along the way',NULL,NULL,NULL,NULL,'default',NULL,3,1,'2026-10-26 02:36:55','2026-10-26 02:36:55'),(19,2,'features',NULL,'Methodology','How we deliver',NULL,NULL,'{\"items\": [{\"icon\": \"arrow-path-rounded-square\", \"title\": \"Agile, iterative delivery\", \"description\": \"Short cycles, frequent demos and continuous feedback.\"}, {\"icon\": \"clipboard-document-check\", \"title\": \"Quality engineering\", \"description\": \"Code review, automated testing and CI/CD on every project.\"}, {\"icon\": \"shield-check\", \"title\": \"Security first\", \"description\": \"Threat modelling, least-privilege access and secure defaults.\"}, {\"icon\": \"chat-bubble-left-right\", \"title\": \"Clear communication\", \"description\": \"A dedicated point of contact and transparent reporting.\"}]}',NULL,'muted',NULL,4,1,'2026-10-26 02:36:55','2026-10-26 02:36:55'),(20,2,'tech_stack',NULL,'Expertise','Technical expertise',NULL,NULL,NULL,NULL,'default',NULL,5,1,'2026-10-26 02:36:55','2026-10-26 02:36:55'),(21,2,'team',NULL,'Leadership','The people behind Softec Ai Solution',NULL,NULL,'{\"limit\": 8, \"leadership_only\": true}',NULL,'default',NULL,6,1,'2026-10-26 02:36:55','2026-10-26 02:36:55'),(22,2,'certifications',NULL,'Recognition','Certifications & achievements',NULL,NULL,NULL,NULL,'default',NULL,7,1,'2026-10-26 02:36:55','2026-10-26 02:36:55'),(23,2,'partners',NULL,'Alliances','Partners & strategic alliances',NULL,NULL,'{\"limit\": 12}',NULL,'default',NULL,8,1,'2026-10-26 02:36:55','2026-10-26 02:36:55'),(24,2,'cta',NULL,NULL,'Let’s build something [great] together','Talk to our team about your next product, platform or AI initiative.',NULL,'{\"primary_cta\": {\"url\": \"/start-a-project\", \"label\": \"Start a project\"}, \"secondary_cta\": {\"url\": \"/careers\", \"label\": \"View careers\"}}',NULL,'gradient',NULL,9,1,'2026-10-26 02:36:55','2026-10-26 02:36:55'),(25,3,'engagement_models',NULL,'Pricing & engagement','Choose the model that [fits your project]','Every engagement starts with a free discovery call. Pricing is tailored to scope — we never publish one-size-fits-all prices.',NULL,'{\"items\": [{\"title\": \"Fixed-scope project\", \"best_for\": \"Well-defined projects and MVPs\", \"features\": [\"Detailed discovery and estimate\", \"Milestone-based delivery\", \"Predictable budget\"], \"description\": \"Defined scope, timeline and budget agreed upfront.\", \"highlighted\": false}, {\"title\": \"Dedicated team\", \"best_for\": \"Long-term product development\", \"features\": [\"Flexible team composition\", \"Your priorities, our people\", \"Scale up or down monthly\"], \"description\": \"A cross-functional team that works as an extension of yours.\", \"highlighted\": true}, {\"title\": \"Time & materials\", \"best_for\": \"Evolving scope and R&D\", \"features\": [\"Weekly reporting\", \"Change priorities any time\", \"No long-term lock-in\"], \"description\": \"Pay for the effort used, with full transparency and control.\", \"highlighted\": false}, {\"title\": \"Support & maintenance\", \"best_for\": \"Live products and legacy systems\", \"features\": [\"Security updates\", \"Monitoring and bug fixes\", \"Agreed response times\"], \"description\": \"Ongoing care for applications after launch.\", \"highlighted\": false}]}',NULL,'default',NULL,0,1,'2026-10-26 02:36:55','2026-10-26 02:36:55'),(26,3,'faq',NULL,'FAQ','Questions about pricing',NULL,NULL,'{\"limit\": 6, \"faq_category\": \"pricing\"}',NULL,'default',NULL,1,1,'2026-10-26 02:36:55','2026-10-26 02:36:55'),(27,3,'cta',NULL,NULL,'Not sure which model fits?','Describe your project and we will recommend the most effective approach.',NULL,'{\"primary_cta\": {\"url\": \"/start-a-project\", \"label\": \"Request an estimate\"}}',NULL,'gradient',NULL,2,1,'2026-10-26 02:36:55','2026-10-26 02:36:55'),(28,1,'rich_text','about-softec-ai-solution','About Softec Ai Solution','Software, AI and cloud expertise [in one partner]',NULL,'<p>Softec Ai Solution is a software development and AI solutions company. We help startups, growing businesses and established organisations turn ideas into reliable digital products — and make the products they already have faster, safer and smarter.</p>\n<p>Our teams combine product strategy, user experience design, modern engineering, data and cloud operations. That means one coordinated partner can take you from discovery and prototyping through to launch, support and continuous improvement, without the hand-offs that slow projects down. Alongside the technology, we help your people adopt new tools with confidence through clear documentation, training and ongoing support.</p>\n<ul>\n<li><strong><a href=\"/services/custom-software-development\" rel=\"noopener noreferrer\">Custom software</a> and <a href=\"/services/web-application-development\" rel=\"noopener noreferrer\">web applications</a></strong> shaped around how your organisation really works.</li>\n<li><strong><a href=\"/services/generative-ai-ai-agent-development\" rel=\"noopener noreferrer\">Generative AI and AI agents</a></strong> grounded in your own knowledge, with security and human oversight built in.</li>\n<li><strong><a href=\"/services/mobile-application-development\" rel=\"noopener noreferrer\">Mobile apps</a> and <a href=\"/services/cloud-computing-cloud-migration\" rel=\"noopener noreferrer\">cloud platforms</a></strong> designed to perform and scale.</li>\n</ul>\n<p>We work transparently, with clear estimates, regular demos and honest advice about what will deliver value. If you have a project in mind, <a href=\"/start-a-project\" rel=\"noopener noreferrer\">tell us about it</a> and we will suggest a practical way forward.</p>',NULL,NULL,'muted',NULL,13,1,'2026-10-26 04:04:33','2026-10-26 04:04:33'),(29,1,'statement','our-approach','Our approach','We combine product thinking, modern engineering and practical AI to build software people enjoy using and businesses can rely on for years.','Clear plans, honest progress reports and well-documented code, with the custom code we build for you owned by you as agreed in your contract.',NULL,NULL,NULL,'default',NULL,3,1,'2026-10-26 04:04:33','2026-10-26 04:04:33');
/*!40000 ALTER TABLE `page_sections` ENABLE KEYS */;
