INSERT INTO `products` VALUES (1,3,'Orbit CRM','orbit-crm','A modern CRM with AI lead scoring and pipeline automation.','A modern CRM with AI lead scoring and pipeline automation. Demo product for previewing the catalogue.','<h2>Overview</h2><p>A modern CRM with AI lead scoring and pipeline automation. This is placeholder copy demonstrating how product pages present features, audiences and next steps.</p><h2>Who it is for</h2><p>Teams that want to replace manual work with a focused, well-designed tool.</p>',NULL,NULL,NULL,'[{\"icon\": \"users\", \"title\": \"Pipeline management\", \"description\": null}, {\"icon\": \"users\", \"title\": \"AI lead scoring\", \"description\": null}, {\"icon\": \"users\", \"title\": \"Email & calendar sync\", \"description\": null}, {\"icon\": \"users\", \"title\": \"Custom dashboards\", \"description\": null}, {\"icon\": \"users\", \"title\": \"Role-based access\", \"description\": null}, {\"icon\": \"users\", \"title\": \"Open API\", \"description\": null}]','[{\"icon\": \"rocket-launch\", \"title\": \"Faster onboarding\", \"description\": \"Get started quickly with guided setup.\"}, {\"icon\": \"shield-check\", \"title\": \"Secure by default\", \"description\": \"Role-based access and audit logging.\"}, {\"icon\": \"adjustments-horizontal\", \"title\": \"Customisable\", \"description\": \"Adapted to your workflows by our team.\"}]','Small and mid-sized teams, and enterprises looking for a configurable solution.','quote_only','Pricing depends on users, modules and deployment model.',0,NULL,1,'available',NULL,NULL,NULL,'published','2026-10-26 02:36:56',1,0,1,NULL,NULL,'2026-10-26 02:36:56','2026-10-26 02:36:56',NULL,NULL),(2,2,'Nimbus Assist','nimbus-assist','An AI knowledge assistant grounded in your company documents.','An AI knowledge assistant grounded in your company documents. Demo product for previewing the catalogue.','<h2>Overview</h2><p>An AI knowledge assistant grounded in your company documents. This is placeholder copy de