INSERT INTO `seo_meta` VALUES (1,'service',7,'AI & Machine Learning Development | Softec Ai Solution','Practical AI and machine learning: forecasting, classification, computer vision and NLP built around real business problems and deployed responsibly.',NULL,NULL,NULL,NULL,1,1,'AI and machine learning development',NULL,'2026-10-26 04:04:33','2026-10-26 04:04:33'),(2,'service',6,'API Development & System Integration | Softec Ai Solution','Secure, documented APIs and reliable integrations that connect your CRM, ERP, payments and SaaS tools so data flows automatically across systems.',NULL,NULL,NULL,NULL,1,1,'API development and system integration',NULL,'2026-10-26 04:04:33','2026-10-26 04:04:33'),(3,'service',9,'Business Process Automation Services | Softec Ai Solution','Automate repetitive work with integrations, workflow engines, RPA and AI document processing — fewer manual steps, fewer errors and faster turnaround.',NULL,NULL,NULL,NULL,1,1,'business process automation services',NULL,'2026-10-26 04:04:33','2026-10-26 04:04:33'),(4,'service',11,'Cloud Migration & Cloud Services | Softec Ai Solution','Plan and execute low-risk cloud migrations to AWS, Azure or Google Cloud, then optimise for cost, performance, resilience and security.',NULL,NULL,NULL,NULL,1,1,'cloud migration services',NULL,'2026-10-26 04:04:33','2026-10-26 04:04:33'),(5,'service',15,'CRM & ERP Solutions: Implementation & Custom Development','CRM and ERP implementation, customisation and integration — or tailored custom systems — that unify customers, sales, operations and finance.',NULL,NULL,NULL,NULL,1,1,'CRM and ERP solutions',NULL,'2026-10-26 04:04:33','2026-10-26 04:04:33'),(6,'service',1,'Custom Software Development Company | Softec Ai Solution','Bespoke software built around your processes — secure, scalable and maintainable. Discovery, design, development and long-term support in one team.',NULL,NULL,NULL,NULL,1,1,'custom software development company',NULL,'2026-10-26 04:04:33','2026-10-26 04:04:33'),(7,'service',14,'Cybersecurity Consulting Services | Softec Ai Solution','Practical cybersecurity consulting: risk assessments, application security reviews, cloud hardening, identity management and incident response planning.',NULL,NULL,NULL,NULL,1,1,'cybersecurity consulting',NULL,'2026-10-26 04:04:33','2026-10-26 04:04:33'),(8,'service',10,'Data Analytics & Business Intelligence | Softec Ai Solution','Reliable data pipelines, warehouses and dashboards that give every team a single source of truth — so decisions are based on data you can trust.',NULL,NULL,NULL,NULL,1,1,'data analytics and business intelligence services',NULL,'2026-10-26 04:04:33','2026-10-26 04:04:33'),(9,'service',12,'DevOps & CI/CD Services | Softec Ai Solution','Automated CI/CD pipelines, infrastructure as code, containers and observability so your team can release frequently, safely and with confidence.',NULL,NULL,NULL,NULL,1,1,'DevOps and CI/CD services',NULL,'2026-10-26 04:04:33','2026-10-26 04:04:33'),(10,'service',16,'Digital Transformation Consulting | Softec Ai Solution','Pragmatic digital transformation consulting: maturity assessments, prioritised roadmaps, process redesign and delivery support teams embrace.',NULL,NULL,NULL,NULL,1,1,'digital transformation consulting',NULL,'2026-10-26 04:04:33','2026-10-26 04:04:33'),(11,'service',5,'E-commerce Development Services | Softec Ai Solution','High-converting e-commerce: fast storefronts, smooth checkout, payment and inventory integrations and easy catalogue management for growing brands.',NULL,NULL,NULL,NULL,1,1,'e-commerce development',NULL,'2026-10-26 04:04:33','2026-10-26 04:04:33'),(12,'service',8,'Generative AI & AI Agent Development | Softec Ai Solution','Generative AI assistants, RAG knowledge search and AI agents grounded in your data — with guardrails, evaluation, privacy controls and human oversight.',NULL,NULL,NULL,NULL,1,1,'generative AI development company',NULL,'2026-10-26 04:04:33','2026-10-26 04:04:33'),(13,'servic